	\begin{equation}\label{eq:ld-sandwich-2}
		A^x_{[\operatorname{eval}_y(\cdot) = (a_1,\,a_2,\,\dots,\,a_k)]} \ot \Id_B \simeq_{k(\delta+\eps)^{1/2}} \Id_A \ot C^x_{[\operatorname{eval}_y(\cdot) = (a_1,\,a_2,\,\dots,\,a_k)]}\,.
